-- Register from data: the first-loaded component may own the visible shell.
do
	local Z = CoD.ZStatsSettings
	local en = Z.Catalogs.en or {}
	local byEnglish, ambiguous, byDvar = {}, {}, {}
	for key, english in next, en do
		if byEnglish[english] == nil and not ambiguous[english] then byEnglish[english] = key
		elseif byEnglish[english] ~= key then byEnglish[english] = nil; ambiguous[english] = true end
		local dvar = string.match( key, '^setting%.(zs_[%w_]+)$' ) or string.match( key, '^hint%.(zs_[%w_]+)$' )
		if dvar == nil then dvar = string.match( key, '^choice%.(zs_[%w_]+)%.' ) end
		if dvar ~= nil then
			local family = byDvar[dvar] or {}
			if family[english] == nil then family[english] = key elseif family[english] ~= key then family[english] = false end
			byDvar[dvar] = family
		end
	end
	local function held( english, holder, fields )
		if type( holder ) ~= 'table' then return nil end
		for _, field in ipairs( fields ) do
			local key = holder[field]
			if type( key ) == 'string' and en[key] == english then return key end
		end
	end
	local function find( english, context )
		local row = type( context ) == 'table' and context.row or nil
		local tab = type( context ) == 'table' and context.tab or nil
		local key = held( english, row, { 'labelKey', 'hintKey', 'boundaryKey', 'scopeKey' } )
		if key ~= nil then return key end
		if type( row ) == 'table' and type( row.choiceKeys ) == 'table' then
			for _, choiceKey in ipairs( row.choiceKeys ) do if en[choiceKey] == english then return choiceKey end end
		end
		if type( row ) == 'table' and type( row.dvar ) == 'string' then
			local family = byDvar[row.dvar]
			if family ~= nil and family[english] then return family[english] end
		end
		key = held( english, tab, { 'labelKey', 'titleKey', 'hintKey' } )
		if key ~= nil then return key end
		return byEnglish[english]
	end
	CoD.ZBundleSettings = CoD.ZBundleSettings or {}
	CoD.ZBundleSettings.Localizers = CoD.ZBundleSettings.Localizers or {}
	CoD.ZBundleSettings.Localizers.zstats = { version = 1, text = function ( english, context )
		if type( english ) ~= 'string' or english == '' then return english end
		local key = find( english, context )
		if key == nil then return english end
		return Z.Text( key, english )
	end }
	local shellKeys, shellCatalogs = {}, {}
	for language, entries in next, Z.Catalogs do
		local translated = {}
		for key, english in next, en do
			if string.sub( key, 1, 6 ) == 'shell.' then translated[english] = entries[key] or english end
		end
		shellCatalogs[language] = translated
	end
	for english in next, shellCatalogs.en do shellKeys[english] = true end
	CoD.ZStatsLocalization = { ShellKeys = shellKeys, Catalogs = shellCatalogs,
		Text = function ( english )
			if not shellKeys[english] then return english end
			local key = byEnglish[english]
			if key == nil or string.sub( key, 1, 6 ) ~= 'shell.' then
				for candidate, value in next, en do
					if value == english and string.sub( candidate, 1, 6 ) == 'shell.' then key = candidate; break end
				end
			end
			return key and Z.Text( key, english ) or english
		end }
end
